import React, { useEffect, useRef, memo } from 'react';
import './NiftyChart.css';

const NiftyChart = () => {
  const containerRef = useRef();

  useEffect(() => {
    if (containerRef.current) {
        // 1. Wipe clean to prevent React StrictMode duplicates
        containerRef.current.innerHTML = '';

        // 2. Set up the exact container structure TradingView needs
        const innerDiv = document.createElement('div');
        innerDiv.className = 'tradingview-widget-container__widget';
        innerDiv.style.height = "calc(100% - 32px)";
        innerDiv.style.width = "100%";
        containerRef.current.appendChild(innerDiv);

        // 3. Inject the Advanced Chart Script
        const script = document.createElement('script');
        script.src = 'https://s3.tradingview.com/external-embedding/embed-widget-advanced-chart.js';
        script.type = 'text/javascript';
        script.async = true;

        // 4. Configure the interactive widget
        script.innerHTML = JSON.stringify({
          "autosize": true,
          "symbol": "BSE:SENSEX",
          "interval": "D", // Daily timeframe by default
          "timezone": "Asia/Kolkata",
          "theme": "light",
          "style": "1", // 1 = Candlestick chart
          "locale": "en_IN",
          "enable_publishing": false,
          "backgroundColor": "#ffffff",
          "gridColor": "rgba(20, 196, 181, 0.1)", // Custom subtle teal grid lines
          "hide_legend": false,
          "save_image": false,
          "calendar": false,
          "support_host": "https://www.tradingview.com"
        });

        containerRef.current.appendChild(script);
    }
  }, []);

  return (
    // We pass a specific height class so the autosize script knows how big to grow
    <div className="chart-widget-block advanced-chart-block">
      <h3 className="chart-title">Market Analysis: BSE SENSEX</h3>
      <div className="tradingview-widget-container" ref={containerRef} style={{ height: '100%', width: '100%' }}></div>
    </div>
  );
};

export default memo(NiftyChart);
